INSERT INTO "books" ("id", "title", "author", "category", "price", "rating", "short_description", "description", "image")
VALUES
('1', 'The Alchemist ', 'Paulo Coelho', 'Fiction', 450, 4.8, 'A young shepherd follows his dreams in search of a hidden treasure.', 'The Alchemist tells the inspiring story of Santiago, a young shepherd from Andalusia who dreams of discovering a treasure hidden near the Egyptian pyramids. Encouraged by mysterious encounters and guided by his desire to fulfil his personal legend, Santiago leaves behind his familiar life and begins an extraordinary journey across deserts and distant lands. Along the way, he meets different people who teach him valuable lessons about courage, love, failure, destiny, and the importance of listening to his heart. The journey ultimately shows him that the greatest treasures are often found through the experiences and lessons gained while pursuing our dreams.', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f'),
('2', 'Atomic Habits', 'James Clear', 'Self Development', 650, 4.9, 'A practical guide to creating good habits through small and consistent improvements.', 'Atomic Habits explains how small changes in daily behaviour can produce remarkable results over time. James Clear presents a practical system for building positive habits and breaking negative ones by focusing on the systems behind our behaviour rather than relying only on motivation. The book explains how habits are formed, how the environment influences our actions, and how making tiny improvements consistently can lead to significant long-term progress. It provides useful strategies for creating better routines, overcoming bad habits, staying consistent, and becoming the kind of person who naturally follows positive behaviours.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794'),
('3', 'Rich Dad Poor Dad', 'Robert T. Kiyosaki', 'Finance', 550, 4.7, 'A personal finance classic about money, investing, and financial education.', 'Rich Dad Poor Dad presents the author''s experiences with two influential father figures who had very different approaches to money and financial education. Robert Kiyosaki uses these experiences to explain how people can develop a stronger understanding of income, expenses, assets, liabilities, investing, and financial independence. The book challenges traditional ideas about employment and wealth and encourages readers to think about how money can work for them rather than simply working for money. It also highlights the importance of financial knowledge, entrepreneurship, and long-term thinking.', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f'),
('4', 'The Psychology of Money', 'Morgan Housel', 'Finance', 700, 4.8, 'An insightful look at how emotions and behaviour influence financial decisions.', 'The Psychology of Money explores the often-overlooked relationship between human behaviour and financial decisions. Morgan Housel uses a collection of engaging stories and observations to explain why people think differently about wealth, spending, saving, investing, risk, and success. The book demonstrates that financial outcomes are influenced not only by knowledge and mathematics but also by personal experiences, emotions, habits, and beliefs. It encourages readers to develop patience, make thoughtful financial decisions, avoid unnecessary risks, and understand that building wealth is often a long-term process.', 'https://images.unsplash.com/photo-1559526324-593bc073d938'),
('5', 'Think and Grow Rich', 'Napoleon Hill', 'Motivation', 400, 4.6, 'A classic guide to developing a success-oriented mindset and achieving goals.', 'Think and Grow Rich is a classic personal development book focused on the principles and mindset associated with achieving success. Napoleon Hill discusses the importance of having clear goals, developing strong desire, maintaining persistence, and believing in one''s ability to succeed. The book draws on ideas gathered from studying successful individuals and presents a number of principles related to personal achievement, leadership, decision-making, and disciplined thinking. Its central message encourages readers to develop a clear vision and consistently work towards their goals despite challenges and setbacks.', 'https://images.unsplash.com/photo-1495446815901-a7297e633e8d'),
('6', 'The Power of Now', 'Eckhart Tolle', 'Personal Development', 600, 4.7, 'A guide to mindfulness and finding greater peace by focusing on the present.', 'The Power of Now explores the idea that much of human stress and dissatisfaction comes from constantly thinking about the past or worrying about the future. Eckhart Tolle encourages readers to develop greater awareness of the present moment and recognise the difference between their thoughts and their deeper sense of awareness. Through practical ideas and reflective explanations, the book discusses mindfulness, acceptance, inner peace, and reducing unnecessary mental activity. It encourages readers to become more present in everyday life and develop a calmer relationship with their thoughts and emotions.', 'https://images.unsplash.com/photo-1507842217343-583bb7270b66'),
('7', '1984', 'George Orwell', 'Dystopian Fiction', 500, 4.8, 'A dystopian story about government control, surveillance, and the loss of personal freedom.', '1984 is a dystopian novel set in a society controlled by an authoritarian government known as the Party. Winston Smith works for the government and secretly questions the political system that controls nearly every aspect of people''s lives. Constant surveillance, manipulated information, restricted language, and psychological control are used to maintain power. As Winston begins to seek truth and personal freedom, he becomes increasingly aware of the dangers of challenging the system. The novel explores themes of political power, censorship, propaganda, privacy, individuality, and the manipulation of truth.', 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e'),
('8', 'The 7 Habits of Highly Effective People', 'Stephen R. Covey', 'Self Development', 750, 4.9, 'A practical framework for improving personal effectiveness, relationships, and leadership.', 'The 7 Habits of Highly Effective People presents a structured approach to personal and professional development. Stephen R. Covey explains seven principles designed to help readers become more effective in managing themselves, working with others, and building meaningful relationships. The book begins with personal responsibility and goal setting before moving towards cooperation, communication, and continuous improvement. It encourages readers to develop proactive behaviour, prioritise important tasks, understand different perspectives, create mutually beneficial relationships, and maintain a balanced approach to personal growth.', 'https://images.unsplash.com/photo-1516979187457-637abb4f9353'),
('9', 'Harry Potter and the Philosopher''s Stone', 'J. K. Rowling', 'Fantasy', 550, 4.9, 'A young boy discovers that he is a wizard and begins his magical journey at Hogwarts.', 'Harry Potter and the Philosopher''s Stone introduces Harry Potter, an orphan who discovers on his eleventh birthday that he is a wizard. After growing up with relatives who treat him poorly, Harry enters the magical world and begins studying at Hogwarts School of Witchcraft and Wizardry. There he makes close friends, learns about magic, discovers more about his family history, and becomes involved in a mysterious adventure surrounding the Philosopher''s Stone. The story combines friendship, courage, mystery, magic, and the struggle between good and evil as Harry begins to understand his place in the wizarding world.', 'https://images.unsplash.com/photo-1621351183012-e2f9972dd9bf'),
('10', 'The Great Gatsby', 'F. Scott Fitzgerald', 'Classic Fiction', 450, 4.6, 'A classic story of love, wealth, ambition, and the American Dream.', 'The Great Gatsby follows Nick Carraway, a young man who moves to Long Island and becomes acquainted with the mysterious millionaire Jay Gatsby. Gatsby is known for his extravagant parties and enormous wealth, but behind his glamorous lifestyle lies a deep personal desire connected to his past. As Nick becomes involved in Gatsby''s world, the story explores relationships between Gatsby, Daisy Buchanan, and others within the wealthy social circles of the time. The novel examines themes of love, ambition, wealth, social class, identity, and the difficulties of achieving the American Dream.', 'https://images.unsplash.com/photo-1511108690759-009324a90311')
INSERT INTO "products" ("id", "product_name", "category", "short_description", "description", "price", "image", "rating", "stock")
VALUES
('1', ' Classic Premium Cotton T-Shirt', 'Fashion', 'Soft cotton T-shirt for comfortable everyday wear.', 'The Classic Premium Cotton T-Shirt is made from soft and breathable cotton fabric that provides excellent comfort throughout the day. Its simple and stylish design makes it suitable for casual outings, shopping, travelling, university and everyday home use. The durable fabric and quality stitching help maintain its shape and appearance even after regular washing. It can be easily paired with jeans, trousers or shorts for a clean and comfortable everyday look.', 650, 'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab', 4.5, 25),
('2', 'Professional Running Shoes', 'Footwear', 'Lightweight shoes for running and daily activities.', 'Professional Running Shoes are designed to provide comfort, stability and support during running, walking and other daily activities. The lightweight construction makes them comfortable to wear for longer periods, while the cushioned sole helps provide better support with every step. The breathable upper material allows airflow to keep your feet comfortable. These shoes are suitable for gym workouts, morning walks, running, travelling and casual everyday use.', 2200, 'https://images.unsplash.com/photo-1542291026-7eec264c27ff', 4.7, 15),
('3', 'Premium Leather Backpack', 'Bags', 'Stylish leather backpack for work, study and travel.', 'The Premium Leather Backpack offers a combination of stylish design, durability and practical storage. It provides enough space for books, notebooks, documents, a laptop, charger and other everyday essentials. Multiple compartments help keep your belongings organised and easy to access. The comfortable shoulder straps make it convenient to carry during work, study or travel. Its classic appearance makes it suitable for both professional and casual environments.', 1800, 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62', 4.6, 12),
('4', 'Advanced Smart Watch', 'Electronics', 'Modern smartwatch for activity tracking and notifications.', 'The Advanced Smart Watch is a modern wearable designed to keep you connected while helping you monitor your daily activities. Its clear digital display makes it easy to check the time, notifications and activity information. The lightweight design provides comfortable use throughout the day, whether you are working, exercising or travelling. With its stylish appearance and practical features, it is a useful accessory for anyone looking for a modern everyday smartwatch.', 3500, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30', 4.4, 18),
('5', 'Wireless Bluetooth Headphones', 'Electronics', 'Comfortable headphones with clear wireless audio.', 'Wireless Bluetooth Headphones provide a convenient and comfortable listening experience without the need for wired connections. They are suitable for listening to music, watching videos, attending online meetings, studying and making calls. The comfortable ear cushions are designed for extended use, while Bluetooth connectivity provides freedom of movement. The clear and balanced audio makes them suitable for everyday entertainment and communication at home, work, school or while travelling.', 2800, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e', 4.8, 20),
('6', 'Classic Denim Jacket', 'Fashion', 'Stylish denim jacket for casual everyday outfits.', 'The Classic Denim Jacket is a versatile fashion essential designed for casual and everyday wear. Made from durable denim fabric, it provides a comfortable fit while offering a timeless appearance. The jacket can be paired with T-shirts, shirts, jeans or trousers to create a variety of stylish outfits. Its practical design makes it suitable for travelling, evening outings, casual meetings and regular outdoor activities.', 1850, 'https://images.unsplash.com/photo-1551028719-00167b16eac5', 4.5, 20),
('7', 'Casual Polo Shirt', 'Fashion', 'Comfortable polo shirt with a clean casual design.', 'The Casual Polo Shirt is made from comfortable fabric that is suitable for everyday activities and casual occasions. Its classic collar and simple design provide a smart yet relaxed appearance. The shirt can be worn with jeans, chinos or trousers and is suitable for shopping, office-casual environments, travelling and social gatherings. Its lightweight construction makes it comfortable for regular use.', 850, 'https://images.unsplash.com/photo-1711355249709-1733df63e028', 4.3, 30),
('8', 'Classic Leather Wallet', 'Accessories', 'Compact leather wallet for cards, cash and ID.', 'The Classic Leather Wallet is designed for carrying everyday essentials such as cash, bank cards and identification cards. Its compact design makes it easy to carry in a pocket while providing organised storage for important items. The durable leather-style material gives the wallet a classic appearance and makes it suitable for both professional and casual use. It is also a practical gift choice for family and friends.', 750, 'https://images.unsplash.com/photo-1627123424574-724758594e93', 4.6, 35),
('9', 'Premium Sunglasses', 'Accessories', 'Modern sunglasses with a stylish everyday design.', 'Premium Sunglasses combine a modern appearance with practical everyday usability. The lightweight frame provides comfortable wear, while the classic design makes them suitable for different outfits and occasions. They are ideal for outdoor activities, travelling, driving and casual outings. Their stylish appearance also makes them a useful fashion accessory for completing a modern everyday look.', 950, 'https://images.unsplash.com/photo-1511499767150-a48a237f0083', 4.4, 22),
('10', 'Sports Training T-Shirt', 'Sports', 'Lightweight sports T-shirt for workouts and training.', 'The Sports Training T-Shirt is designed for people who enjoy exercise, gym workouts and outdoor activities. Its lightweight fabric provides comfortable movement during training and everyday exercise sessions. The simple athletic design makes it suitable for running, cycling, gym workouts and casual sports activities. It can also be used as a comfortable everyday T-shirt for an active lifestyle.', 750, 'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab', 4.5, 28),
('11', 'Travel Sports Bag', 'Bags', 'Spacious sports bag for gym and short trips.', 'The Travel Sports Bag provides practical storage for clothing, shoes, towels and other personal belongings. Its spacious main compartment allows you to carry your essentials comfortably, while additional pockets help keep smaller items organised. The durable construction makes it suitable for gym sessions, sports activities, weekend trips and short travel. Its practical design makes it a useful companion for an active lifestyle.', 1450, 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62', 4.5, 16),
('12', 'Portable Bluetooth Speaker', 'Electronics', 'Compact wireless speaker for music anywhere.', 'The Portable Bluetooth Speaker is designed for convenient wireless music playback at home, outdoors or while travelling. Its compact size makes it easy to carry, while Bluetooth connectivity allows you to connect compatible smartphones, tablets and other devices. The speaker is suitable for listening to music, podcasts and videos. Its simple design and portability make it a useful entertainment accessory for everyday use.', 1650, 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1', 4.6, 14),
('13', 'Mechanical Gaming Keyboard', 'Computer Accessories', 'Responsive mechanical keyboard for gaming and work.', 'The Mechanical Gaming Keyboard is designed for gamers, programmers and users who spend long hours typing. Its responsive mechanical-style keys provide a comfortable and satisfying typing experience. The durable construction is suitable for regular use at home or in the office. It can be used for gaming, programming, writing, browsing and other computer activities where reliable keyboard performance is important.', 3200, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3', 4.7, 10),
('14', 'Wireless Computer Mouse', 'Computer Accessories', 'Comfortable wireless mouse for everyday computer use.', 'The Wireless Computer Mouse provides convenient and comfortable control for laptops and desktop computers without requiring a traditional wired connection. Its compact design makes it easy to use at home, work or while travelling. The mouse is suitable for browsing, office work, programming, graphic tasks and general computer use. Its simple design makes it an excellent everyday computer accessory.', 850, 'https://images.unsplash.com/photo-1527814050087-3793815479db', 4.4, 25),
('15', 'Stainless Steel Water Bottle', 'Lifestyle', 'Durable reusable bottle for everyday hydration.', 'The Stainless Steel Water Bottle is designed for convenient everyday hydration at work, school, gym sessions and outdoor activities. Its durable construction makes it suitable for regular use, while the reusable design provides a practical alternative to disposable bottles. The compact shape makes it easy to carry in a backpack or travel bag. It is a useful everyday accessory for maintaining a convenient drinking routine.', 650, 'https://images.unsplash.com/photo-1602143407151-7111542de6e8', 4.6, 40),
('16', 'Modern Table Lamp', 'Home & Living', 'Minimal table lamp for study and bedroom use.', 'The Modern Table Lamp features a simple and attractive design that works well in bedrooms, study areas, offices and living spaces. It provides a comfortable lighting solution for reading, studying, working or creating a relaxing atmosphere. Its compact design allows it to fit easily on desks, bedside tables and small furniture. The clean appearance makes it suitable for modern home and office interiors.', 1250, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c', 4.5, 18),
('17', 'Wireless Charging Pad', 'Mobile Accessories', 'Convenient wireless charging pad for compatible devices.', 'The Wireless Charging Pad provides a convenient way to charge compatible smartphones and other supported devices without repeatedly connecting a charging cable. Its compact design takes up very little space on a desk or bedside table. It is suitable for home, office and travel use and helps keep your charging area organised. Simply place a compatible device on the charging surface for convenient everyday charging.', 1100, 'https://images.unsplash.com/photo-1586953208448-b95a79798f07', 4.3, 21)
